recipes.code:
{
  "inputs": [
    {
      "id": "skill-token",
      "type": "promptString",
      "description": "sk_live_ API token from Skill portal (POST /api/v1/tokens)",
      "password": true
    }
  ],
  "servers": {
    "creator-skill-v2": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "creator-skill-v2@0.2.1"
      ],
      "env": {
        "SKILL_TOKEN": "${input:skill-token}",
        "SKILL_MCP_URL": "<skill-mcp-url>"
      }
    }
  }
}
